import {useCallback} from 'react';
import {createSearchParams, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import ReadComponent from "../components/Manager/ReadComponent";

const ReadPage = () => {

      const {userId} = useParams()

      const navigate = useNavigate()

      const [queryParams] = useSearchParams()

      const page = queryParams.get('page') ? parseInt(queryParams.get('page')) : 1
      const size = queryParams.get('size') ? parseInt(queryParams.get('size')) : 10

      const queryStr = createSearchParams({page, size}).toString()

      const moveToModify = useCallback((userId) => {

          navigate({
              pathname: `/manager/modify/${userId}`,
              search: queryStr
          })
      }, [userId, page, size])

      const moveToList = useCallback(() => {

         navigate({
             pathname: '/manager/list',
             search: queryStr
         })
      }, [page, size]);

      return (
       <div className="font-extrabold w-full bg-white mt-6">
       <div className="text-2xl "> Todo Read Page Component {userId} </div>
        <ReadComponent userId={userId}></ReadComponent>
       </div>
      );
}
export default ReadPage;
